import{_ as t,a as r,o as n,ai as o}from"./chunks/framework.BbOtTPsL.js";const g=JSON.parse('{"title":"Reporting — Overview (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Reporting Overview","query":"query AdminReportingOverview($type: String, $start: String, $end: String, $channel: String) {\\n  statsAdminReportingOverview(type: $type, start: $start, end: $end, channel: $channel) {\\n    entity\\n    type\\n    dateRange\\n    statistics\\n  }\\n}\\n","variables":"{ \\"type\\": \\"total-sales\\" }\\n","response":"{\\n  \\"data\\": {\\n    \\"statsAdminReportingOverview\\": {\\n      \\"entity\\": \\"overview\\",\\n      \\"type\\": \\"total-sales\\",\\n      \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n      \\"statistics\\": {\\n        \\"sales\\": { \\"previous\\": 27243.5, \\"current\\": 9697.53, \\"formatted_total\\": \\"$9,697.53\\", \\"progress\\": -64.32 },\\n        \\"over_time\\": {\\n          \\"previous\\": [ { \\"label\\": \\"10 Apr\\", \\"total\\": 4200, \\"count\\": 6 } ],\\n          \\"current\\": [ { \\"label\\": \\"10 May\\", \\"total\\": 8500, \\"count\\": 12 } ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"},{"id":"gql-filtered","title":"Reporting Overview (Filtered by date + channel)","query":"query AdminReportingOverview($type: String, $start: String, $end: String, $channel: String) {\\n  statsAdminReportingOverview(type: $type, start: $start, end: $end, channel: $channel) {\\n    entity\\n    type\\n    dateRange\\n    statistics\\n  }\\n}\\n","variables":"{ \\"type\\": \\"total-sales\\", \\"start\\": \\"2026-05-10\\", \\"end\\": \\"2026-06-09\\", \\"channel\\": \\"default\\" }\\n","response":"{\\n  \\"data\\": {\\n    \\"statsAdminReportingOverview\\": {\\n      \\"entity\\": \\"overview\\",\\n      \\"type\\": \\"total-sales\\",\\n      \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n      \\"statistics\\": {\\n        \\"sales\\": { \\"previous\\": 27243.5, \\"current\\": 9697.53, \\"formatted_total\\": \\"$9,697.53\\", \\"progress\\": -64.32 },\\n        \\"over_time\\": {\\n          \\"previous\\": [ { \\"label\\": \\"10 Apr\\", \\"total\\": 4200, \\"count\\": 6 } ],\\n          \\"current\\": [ { \\"label\\": \\"10 May\\", \\"total\\": 8500, \\"count\\": 12 } ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/reporting/overview.md","filePath":"api/graphql-api/admin/reporting/overview.md","lastUpdated":1781099665000}'),a={name:"api/graphql-api/admin/reporting/overview.md"};function i(s,e,d,c,l,p){return n(),r("div",null,e[0]||(e[0]=[o('<h1 id="reporting-—-overview-graphql" tabindex="-1">Reporting — Overview (GraphQL) <a class="header-anchor" href="#reporting-—-overview-graphql" aria-label="Permalink to &quot;Reporting — Overview (GraphQL)&quot;">​</a></h1><p>Query: <code>statsAdminReportingOverview</code>.</p><p>The Overview query returns a single headline figure across the whole store for the chosen <code>type</code>. It is an API convenience aggregation — there is <strong>no</strong> matching &quot;Overview&quot; screen in the admin panel (the admin Reporting menu goes straight to Sales / Customers / Products). Use it to fetch one top-line number without having to call the per-section queries.</p><p>The <code>type</code> argument picks which headline you get back:</p><ul><li><code>total-sales</code> (default) — total revenue for the period.</li><li><code>total-orders</code> — number of orders placed.</li><li><code>total-customers</code> — number of new customers.</li><li><code>top-selling-products-by-revenue</code> — the best-selling product by revenue.</li></ul><p>The <code>statistics</code> object carries a previous-vs-current comparison plus a <code>progress</code> percentage (how the current window compares to the previous one), and for time-based types an <code>over_time</code> series of per-day data points for charting. <code>dateRange</code> reports the two comparison windows — <code>current</code> is the window you asked for, <code>previous</code> is the equal-length window immediately before it.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arg</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>type</code></td><td>String</td><td><code>total-sales</code> (default), <code>total-orders</code>, <code>total-customers</code>, <code>top-selling-products-by-revenue</code>.</td></tr><tr><td><code>start</code></td><td>String</td><td>Start of the reporting window (<code>YYYY-MM-DD</code>).</td></tr><tr><td><code>end</code></td><td>String</td><td>End of the reporting window (<code>YYYY-MM-DD</code>).</td></tr><tr><td><code>channel</code></td><td>String</td><td>Channel code (e.g. <code>default</code>) — scopes the figures to one storefront channel.</td></tr></tbody></table><p>Unlike the Sales / Customers / Products queries, the Overview query has <strong>no View Details and no Export</strong> — it is a top-line summary only. Reporting requires only authentication; there is no permission gate.</p>',9)]))}const h=t(a,[["render",i]]);export{g as __pageData,h as default};
